float CTCHeroMorph::GetMorphStrength(EHeroMorphType type) const
{
    switch (type) {
    case 0:
        return 0.0f;
    case 1:
        if (Tan >= 0.5f)
            return (Tan - 0.5f) * 2.0f;
        break;
    case 2:
        if (Tan < 0.5f)
            return (0.5f - Tan) * 2.0f;
        break;
    case 4: {
        float v = Age - 0.4f;
        if (v < 0.0f)
            v = 0.0f;
        return v * (1.0f / 0.6f);
    }
    case 5: {
        float v = Age - 0.2f;
        if (v < 0.0f)
            v = 0.0f;
        return v * (1.0f / 0.8f);
    }
    case 17:
        return Berserk;
    case 6:
        if (Morality < 0.5f)
            return (0.5f - Morality) * 2.0f;
        break;
    case 7:
        if (Morality >= 0.5f)
            return (Morality - 0.5f) * 2.0f;
        break;
    case 9:
    {
        float difference;
        return GFLimitReturn(difference = GetMorphStrength((EHeroMorphType)8) - Fatness, 0.0f, 1.0f);
    }
    case 10:
        return Will;
    case 11: {
        float difference = Strength - Skill;
        float high = 1.0f;
        float low = 0.0f;
        return GFLimitReturn(difference, low, high);
    }
    case 12:
        if (Strength >= 0.5f)
            return (Strength - 0.5f) * 2.0f;
        break;
    case 13:
        if (Strength < 0.5f)
            return (0.5f - Strength) * 2.0f;
        break;
    case 14:
        return Fatness;
    case 8:
    case 15:
        return Skill;
    case 16:
        return GetMorphStrength((EHeroMorphType)6);
    case 18:
        return Teenager ? 1.0f : 0.0f;
    }
    return 0.0f;
}

